// Parse Gemini response and extract alerts array
const geminiResponse = $input.first().json;
const text = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text ?? '[]';

// Clean potential markdown fences
const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  const alertas = JSON.parse(cleaned);
  if (!Array.isArray(alertas) || alertas.length === 0) {
    return [{ json: { _skip: true, reason: 'No alerts generated' } }];
  }
  return alertas.map(a => ({
    json: {
      tipo: a.tipo || 'general',
      severidad: a.severidad || 'media',
      categoria: a.categoria || 'climatico',
      mensaje: (a.mensaje || '').substring(0, 200),
      racional: a.racional || '',
      recomendacion: a.recomendacion || '',
      confianza: typeof a.confianza === 'number' ? a.confianza : 0.8,
      loteId: a.loteId || null,
      fecha: new Date().toISOString().split('T')[0]
    }
  }));
} catch (e) {
  return [{ json: { _skip: true, reason: 'Parse error: ' + e.message } }];
}
